 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    diagonals = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                d = c - r
                if d in diagonals and diagonals[d] != value:
                    raise ValueError("conflicting colors on one diagonal")
                diagonals[d] = value
    if not diagonals:
        return [row[:] for row in grid]
    if len(set(diagonals.values())) == 1:
        return [[next(iter(diagonals.values())) for _ in range(w)] for _ in range(h)]
    period = len(diagonals)
    pattern = {}
    for d, value in diagonals.items():
        phase = d % period
        if phase in pattern and pattern[phase] != value:
            raise ValueError("inconsistent diagonal period")
        pattern[phase] = value
    if len(pattern) != period:
        raise ValueError("diagonal phases do not cover the inferred period")
    return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
